package com.muxigame.city;
import java.util.*;
import net.minecraft.server.MinecraftServer;

/** Daily bounded household decisions. No new jobs, people, capital, stock or promised orders. */
public final class CityOpportunities {
 static boolean bakery(MinecraftServer s,UUID city){var t=CityTrade.get(s);return t.state.businesses.values().stream().anyMatch(b->b.city.equals(city)&&b.kind.equals("baker")&&t.usable(s,b));}
 static int expectedBread(MinecraftServer s,UUID city){var t=CityTrade.get(s);int grain=t.quote(s,city,0,RuralSettlement.get(s).state.simulationTicks);return bakery(s,city)?Math.min(t.quote(s,city,1,RuralSettlement.get(s).state.simulationTicks),grain+2):t.quote(s,city,1,RuralSettlement.get(s).state.simulationTicks);}
 static boolean buyPrepared(MinecraftServer s,RuralRules.Family family,boolean secondary){var d=RuralSettlement.get(s);var t=CityTrade.get(s);int grain=t.quote(s,family.city,0,d.state.simulationTicks);double earned=0;var home=t.state.households.get(family.id);if(home!=null&&home.processor!=null){UUID id=home.processor;long since=d.state.simulationTicks-3*24000L;earned=CityEconomy.get(s).journal.stream().filter(e->e.tick()>=since&&e.to().equals(CityEconomy.person(id))&&Set.of("WORK_WAGE","PRIVATE_WORK_WAGE","OWNER_DRAW").contains(e.kind())).mapToLong(CityEconomy.Entry::amount).sum()/3.0;}int opportunity=(int)Math.floor(earned*.5/Math.max(1,RuralRules.demand(family,d.state.people)*2/3.0));return FoodMarketRules.buyPrepared(grain,expectedBread(s,family.city),opportunity,true);}
 static long budget(MinecraftServer s,CityTrade.Business b){var t=CityTrade.get(s);var d=RuralSettlement.get(s);var p=d.state.people.get(b.owner);if(p==null||p.dead)return 0;var f=d.state.families.get(p.family);long reserve=FamilyBudget.reserve(s,f);return CityEconomy.get(s).balance(b.account)+Math.min(CityEconomy.get(s).balance(CityEconomy.person(p.id)),Math.max(0,t.familyMoney(s,f)-reserve));}
 static boolean viable(MinecraftServer s,CityTrade.Business b){var t=CityTrade.get(s);if(!CityCurrency.model(s,b.city))return false;long cash=budget(s,b);long now=RuralSettlement.get(s).state.simulationTicks;if(b.kind.equals("baker"))return b.stock[0].count>0||cash>=t.quote(s,b.city,0,now)+4&&t.quote(s,b.city,1,now)>t.quote(s,b.city,0,now);if(b.kind.equals("supplier"))return cash>=4&&(t.quote(s,b.city,2,now)>=4&&b.stock[2].count+b.listed[2].count<t.state.config.supplierCap||t.quote(s,b.city,3,now)>=4&&b.stock[3].count+b.listed[3].count<t.state.config.supplierCap);if(!b.kind.equals("procurement")||cash<41)return false;UUID village=CityRoute.village(t,b.city);if(village==null||t.liveHead(s,village)==null)return false;int city=t.quote(s,b.city,0,now),rural=t.quote(s,village,0,now);if(t.stock(s,b.city,0)>0&&CityRoute.ruralBid(s,village)*b.perception>=city*1.5&&cash>=city+40)return true;if(t.stock(s,village,0)>0&&city*b.perception>=rural*1.5&&cash>=rural+40)return true;for(int g=2;g<4;g++)if(t.stock(s,b.city,g)>0&&t.quote(s,village,g,now)*.95*b.perception>=t.quote(s,b.city,g,now)*1.25&&cash>=t.quote(s,b.city,g,now)+40)return true;return false;}
 static void daily(MinecraftServer s,CityData.City c,RuralRules.Family f){var t=CityTrade.get(s);if(!CityCurrency.model(s,c.id))return;var d=RuralSettlement.get(s);for(var site:d.state.sites.values())if(site.city.equals(c.id)&&site.kind.equals("artisan")){var h=CityWorks.at(c,site.pos);if(h!=null)h.artisanWorkshop=true;}CityWorks.updateEmergency(s,c);
  for(var p:RuralRules.members(f,d.state.people))if(p.role==RuralRules.Role.HUNTER&&RuralSuccession.capable(p)){int food=RuralRules.count(d.stocks(f.id),false)+RuralRules.count(d.stocks(f.id),true)+RuralMeat.total(d.stocks(f.id));long reserve=DataCityRules.foodReserve(RuralRules.demand(f,d.state.people),3);if(food<reserve&&(p.hunger()>0||t.familyMoney(s,f)<reserve*t.quote(s,c.id,0,d.state.simulationTicks)))FamilyLivelihood.seek(s,c,p);}
  for(var b:t.state.businesses.values())if(b.city.equals(c.id)&&b.closing&&f.members.contains(b.owner)&&viable(s,b)){var p=d.state.people.get(b.owner);if(!RuralSuccession.capable(p)||p.role!=RuralRules.Role.NONE&&p.role!=RuralRules.Role.VAGRANT)continue;var site=d.state.sites.get(RuralSettlement.key(c.id,b.site));if(site==null||!RuralTools.available(s,site)||site.worker!=null&&!site.worker.equals(p.id)&&CityWorks.living(s,c,site.worker))continue;var h=CityWorks.at(c,site.pos);if(h==null||h.workers.stream().filter(id->CityWorks.living(s,c,id)).count()>=h.workerLimit&&!h.workers.contains(p.id))continue;
   CityRoute.capital(s,b,b.kind.equals("procurement")?80:24);b.worker=p.id;site.worker=p.id;site.vacantSince=0;h.workers.removeIf(id->!CityWorks.living(s,c,id));h.workers.add(p.id);RuralSuccession.setRole(p,switch(b.kind){case "baker"->RuralRules.Role.BAKER;case "supplier"->RuralRules.Role.SUPPLIER;default->RuralRules.Role.PROCUREMENT;});b.closing=false;b.status="使用原有资产恢复经营，没有重发本金";d.log(p.name+"自主复业，私产原样保留");
  }
 }
}

